import{_ as e,o as a,c as s,k as o}from"./chunks/framework.ystBm8og.js";const u=JSON.parse('{"title":"Using the app","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1785751237000}'),r={name:"guide/usage.md"};function n(i,t,d,l,h,c){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="using-the-app" tabindex="-1">Using the app <a class="header-anchor" href="#using-the-app" aria-label="Permalink to &quot;Using the app&quot;">​</a></h1><p>Pomodoro keeps a single focus window, a menu bar tray, and three bottom sheets: <strong>Tasks</strong>, <strong>Sessions</strong>, and <strong>Settings</strong>.</p><h2 id="timer" tabindex="-1">Timer <a class="header-anchor" href="#timer" aria-label="Permalink to &quot;Timer&quot;">​</a></h2><ol><li>Choose <strong>Focus</strong>, <strong>Short</strong>, or <strong>Long</strong> under the dial (segmented control).</li><li>Press the large main button - or <strong>Space</strong> - to start or pause.</li><li><strong>Skip</strong> jumps to the next phase in the cycle.</li><li><strong>Reset</strong> restarts the current phase’s duration.</li></ol><h3 id="defaults" tabindex="-1">Defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to &quot;Defaults&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Phase</th><th>Default length</th></tr></thead><tbody><tr><td>Focus</td><td>25 minutes</td></tr><tr><td>Short break</td><td>5 minutes</td></tr><tr><td>Long break</td><td>15 minutes</td></tr><tr><td>Long break every</td><td>4 completed focus sessions</td></tr></tbody></table><p>All of these are editable in Settings.</p><h3 id="mode-switch-confirm" tabindex="-1">Mode switch confirm <a class="header-anchor" href="#mode-switch-confirm" aria-label="Permalink to &quot;Mode switch confirm&quot;">​</a></h3><p>If a timer is <strong>running or paused</strong>, switching Focus / Short / Long asks for confirmation so you do not lose progress by accident.</p><h3 id="cycle-dots" tabindex="-1">Cycle dots <a class="header-anchor" href="#cycle-dots" aria-label="Permalink to &quot;Cycle dots&quot;">​</a></h3><p>Small dots under the dial show progress toward the next long break (completed focus sessions in the current set).</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><p>Open <strong>Tasks</strong> with the list icon in the title bar.</p><ol><li>Type a title and add a task.</li><li>Press <strong>play</strong> on a row to start <strong>Focus</strong> on that task (sets it active and starts the timer when appropriate).</li><li>Tap a task title to <strong>edit</strong> — rename, set a due date and time, or clear the due date, then <strong>Save</strong>.</li><li>When a Focus phase completes while a task is active, its pomodoro count increments.</li><li>The active task appears as a chip under the dial - click it to reopen Tasks.</li></ol><p>Due dates show under the title. Open tasks turn <strong>soon</strong> within 24 hours and <strong>overdue</strong> after the deadline.</p><p>With <strong>Settings → Notifications</strong> enabled, the app sends native alerts when a task is added and when a due date is approaching (about 24 hours before, 1 hour before, and at the due time). Completed tasks do not get due reminders. Reminders run while the app is open in the tray.</p><p>Mark tasks complete or delete them from the sheet. Data is stored locally (see <a href="/guide/privacy">Privacy</a>).</p><h2 id="sessions-history" tabindex="-1">Sessions history <a class="header-anchor" href="#sessions-history" aria-label="Permalink to &quot;Sessions history&quot;">​</a></h2><p>Open <strong>Sessions</strong> with the chart icon in the title bar, or from <strong>Settings → Sessions</strong>.</p><table tabindex="0"><thead><tr><th>Section</th><th>What it shows</th></tr></thead><tbody><tr><td>Stats</td><td>Focus sessions completed, total focus time, last-7-days count</td></tr><tr><td>Chart</td><td>Daily focus completions for the last 7 days</td></tr><tr><td>List</td><td>Recent sessions - completed, skipped, or stopped</td></tr></tbody></table><p>History is written to a local <strong>SQLite</strong> database when phases end (complete / skip / stop).</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open <strong>Settings</strong> with the gear icon, or <strong>⌘,</strong> on macOS.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td>Focus / short / long durations</td><td>Minutes per phase</td></tr><tr><td>Long break every <em>N</em></td><td>How many focus completions before a long break</td></tr><tr><td>Auto-start breaks</td><td>Start the next break when focus ends</td></tr><tr><td>Auto-start focus</td><td>Start focus when a break ends</td></tr><tr><td>Sound</td><td>Two-tone completion chime</td></tr><tr><td>Notifications</td><td>Native OS notifications on phase complete, task added, and due dates</td></tr><tr><td>Accent color</td><td>Dial + main button color, or <strong>Auto</strong> by phase</td></tr></tbody></table><h2 id="tray" tabindex="-1">Tray <a class="header-anchor" href="#tray" aria-label="Permalink to &quot;Tray&quot;">​</a></h2><p>The menu bar / system tray icon provides quick controls so you can leave the main window in the background while a session runs.</p><h2 id="accent-colors" tabindex="-1">Accent colors <a class="header-anchor" href="#accent-colors" aria-label="Permalink to &quot;Accent colors&quot;">​</a></h2><p>Accent applies to the progress ring and primary button:</p><ul><li><strong>Auto</strong> - red (focus), green (short break), blue (long break) by default phase mapping</li><li>Fixed system-style colors: red, orange, yellow, green, mint, teal, cyan, blue, indigo, purple, pink, brown</li></ul><p>Light and dark UI follow the <strong>system</strong> appearance.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/guide/keyboard">Keyboard shortcuts</a></li><li><a href="/guide/install">Install notes</a></li><li><a href="/develop/setup">Develop from source</a></li></ul>',32)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
